-- v2.4 — a public code is generated by the database, not by omitting a column.
--
-- v2.3 put the public token in a column DEFAULT. That reads well but is wrong
-- in practice: an insert that leaves `code` out is handed the default, so an
-- email grant (which must have code = null) arrived with both targets filled
-- and was rejected by note_shares_one_target. The fix is a BEFORE INSERT
-- trigger that decides from the row itself: a grant with an email gets no
-- code, a grant without one gets a code. Constraints are checked after BEFORE
-- triggers, so the row is consistent by the time it is validated.
--
-- Re-runnable.

alter table public.note_shares alter column code drop default;

create or replace function public.note_shares_mint_code()
returns trigger
language plpgsql
as $$
begin
  if new.code is null and new.email is null then
    /* 64 bits of the same generator the primary keys use */
    new.code := substring(replace(gen_random_uuid()::text, '-', '') from 1 for 16);
  end if;
  return new;
end $$;

drop trigger if exists note_shares_code on public.note_shares;
create trigger note_shares_code
  before insert on public.note_shares
  for each row execute function public.note_shares_mint_code();

comment on function public.note_shares_mint_code() is
  'A public link needs a code, a person grant must not have one. Decided here, not by the client.';
